import AppKit
import SwiftUI

/// The owner's artwork, embedded so every build (the app, the command line, snapshots, tests) draws the same pixels without a resource bundle.
/// Both are black-on-clear masks, drawn as templates in any colour:
/// - `swpLetters`: the "swp" letters exactly as they are in `swamp-logo.psd` (its type layer, exported in full: on the 1024 px icon canvas the s and the p run off the
///   edges). 1096 x 439 px. Source copy: `Resources/Brand/swp-wordmark.png`.
/// - `madeByMark`: the owner's personal mark for the "Made by" line of About, from aaarabic00000000.png, cropped. 388 x 480 px. Source copy: `Resources/Brand/made-by.png`.
enum BrandArtwork {
    static let swpAspect: CGFloat = 1096.0 / 439.0
    static let madeByAspect: CGFloat = 388.0 / 480.0

    @MainActor static let swpLetters: NSImage = template(swpPNG)
    @MainActor static let madeByMark: NSImage = template(madeByPNG)

    private static func template(_ base64: String) -> NSImage {
        let image = Data(base64Encoded: base64).flatMap(NSImage.init(data:)) ?? NSImage(size: NSSize(width: 1, height: 1))
        image.isTemplate = true
        return image
    }

    private static let swpPNG = ""

    private static let madeByPNG = ""
}
